import { createHash } from "node:crypto";
import { chmodSync, constants, existsSync, lstatSync, mkdtempSync, openSync, closeSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";
import { DatabaseSync } from "node:sqlite";

export function resolveRetiredSqliteBundleTarget(root: string, lane: "dev" | "userdata", mainBasename: "product-state-v1.sqlite" | "state.sqlite") {
  if (!root.endsWith(".omnimind")) throw new Error("canonical default root required");
  if (lane !== "dev" && lane !== "userdata") throw new Error("lane required");
  if (mainBasename !== "product-state-v1.sqlite" && mainBasename !== "state.sqlite") throw new Error("retired basename required");
  const main = join(root, lane, mainBasename);
  return { main, sidecars: [main + "-wal", main + "-shm"] };
}

export function createClassifierScratchRoot() {
  const root = mkdtempSync(join(tmpdir(), "omnimind-classifier-"));
  chmodSync(root, 0o700);
  return root;
}

export function copyRetiredSqliteBundleToScratch(retiredBundle: { main: string; sidecars: string[] }, invocationScratchRoot: string) {
  const sourceManifestBefore = [retiredBundle.main, ...retiredBundle.sidecars].map((path) => [basename(path), existsSync(path)]);
  const sourceStatBefore = lstatSync(retiredBundle.main);
  const sourceHandle = openSync(retiredBundle.main, constants.O_RDONLY | constants.O_NOFOLLOW);
  const classifierCopyPath = join(invocationScratchRoot, "classifier.sqlite");
  const copyHandle = openSync(classifierCopyPath, constants.O_CREAT | constants.O_EXCL | constants.O_WRONLY, 0o600);
  const sourceBytes = readFileSync(sourceHandle);
  writeFileSync(copyHandle, sourceBytes);
  closeSync(copyHandle);
  closeSync(sourceHandle);
  const copyBytes = readFileSync(classifierCopyPath);
  const sourceSha256 = createHash("sha256").update(sourceBytes).digest("hex");
  const copySha256 = createHash("sha256").update(copyBytes).digest("hex");
  const sourceStatAfter = lstatSync(retiredBundle.main);
  const copyStat = lstatSync(classifierCopyPath);
  const sourceManifestAfter = [retiredBundle.main, ...retiredBundle.sidecars].map((path) => [basename(path), existsSync(path)]);
  if (sourceStatBefore.ino !== sourceStatAfter.ino || copyStat.nlink !== 1 || sourceBytes.length !== copyBytes.length || sourceSha256 !== copySha256 || JSON.stringify(sourceManifestBefore) !== JSON.stringify(sourceManifestAfter)) throw new Error("copy identity mismatch");
  return classifierCopyPath;
}

export function openClassifierCopyReadOnly(classifierCopyPath: string) {
  return new DatabaseSync(classifierCopyPath, { readOnly: true });
}

export function removeClassifierScratch(invocationScratchRoot: string) {
  if (lstatSync(invocationScratchRoot).isSymbolicLink()) throw new Error("scratch link forbidden");
  rmSync(invocationScratchRoot, { recursive: true, force: false });
}

export function assertClassifierScratchAbsent(invocationScratchRoot: string) {
  if (existsSync(invocationScratchRoot)) throw new Error("scratch retained");
}

export function classifyRetiredSqliteBundle(retiredBundle: { main: string; sidecars: string[] }) {
  const invocationScratchRoot = createClassifierScratchRoot();
  try {
    const classifierCopyPath = copyRetiredSqliteBundleToScratch(retiredBundle, invocationScratchRoot);
    const classifierDatabase = openClassifierCopyReadOnly(classifierCopyPath);
    try {
      return classifierDatabase.prepare("SELECT name FROM sqlite_master").all();
    } finally {
      classifierDatabase.close();
    }
  } finally {
    removeClassifierScratch(invocationScratchRoot);
    assertClassifierScratchAbsent(invocationScratchRoot);
  }
}

export function classifyCanonicalRetired(root: string, lane: "dev" | "userdata", mainBasename: "product-state-v1.sqlite" | "state.sqlite") {
  return classifyRetiredSqliteBundle(resolveRetiredSqliteBundleTarget(root, lane, mainBasename));
}
